-- 3. Inserção ou atualização das Salas na tabela oficial "sala"
-- Evita duplicações caso a sala já tenha sido inserida com a mesma descrição
INSERT INTO "sala" ("descricao", "escola")
SELECT t.descricao, t.escola
FROM _temp_locais t
WHERE NOT EXISTS (
    SELECT 1 FROM "sala" s WHERE s.descricao = t.descricao
);

-- 4. Vincular o sala_id gerado com cada código de local
UPDATE _temp_locais t
SET sala_id = s.id
FROM "sala" s
WHERE s.descricao = t.descricao;

